#!/usr/bin/env node
// Regenerates js/data.bundle.js from data/*.json.
// The bundle is the file:// fallback used by js/data.js when fetch() is unavailable.
// Usage (from the project root):  node tools/build-data-bundle.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const dataDir = join(root, 'data');
const outFile = join(root, 'js', 'data.bundle.js');

// "attendance-history.json" -> "attendanceHistory"
const toKey = (file) => basename(file, '.json').replace(/-([a-z])/g, (_, c) => c.toUpperCase());

const data = {};
for (const file of readdirSync(dataDir).filter((f) => f.endsWith('.json')).sort()) {
  data[toKey(file)] = JSON.parse(readFileSync(join(dataDir, file), 'utf8')); // throws on invalid JSON
}

const banner = '// GENERATED by tools/build-data-bundle.mjs from data/*.json. Do not edit by hand.\n';
// JSON.stringify output is a valid JS expression; escape "<" so the file stays safe if ever inlined.
const body = JSON.stringify(data).replace(/</g, '\\u003c');
writeFileSync(outFile, `${banner}window.__DATA__ = ${body};\n`);
console.log(`Wrote ${outFile} (${Object.keys(data).length} datasets: ${Object.keys(data).join(', ')})`);
